/* @lc app=leetcode id=3267 lang=kotlin */ class Solution { fun sw(s: String): List<String> = s.indices.flatMap { i -> (i + 1 until s.length).map { j -> String(s.toCharArray().also { c -> c[i] = s[j] }.also { c -> c[j] = s[i] }) } } fun ex(st: Set<String>): Set<String> = st + st.flatMap { sw(it) } fun countPairs(nums: IntArray): Int = HashMap<String, Int>().let { cnt -> nums.map { x -> "%07d".format(x).let { p -> (cnt[p] ?: 0).also { ex(ex(setOf(p))).forEach { q -> cnt.merge(q, 1) { a, b -> a + b } } } } }.sum() } }